function solve(a,b,c){if(a.length+b.length!==c.length){return false;}return h(a.length,b.length,(d,e,f)=>d+e===0||f&&(d===0?b[e-1]:a[d-1])===c[d+e-1],(d,e,f,g,h)=>f&&a[d-1]===c[d+e-1]||g&&b[e-1]===c[d+e-1]);}function h(a,b,c,d){const e=new Array(b+1);for(let a=0;a<=b;a++){e[a]=c(0,a,a?e[a-1]:undefined);}for(let f=1;f<=a;f++){let a=e[0];e[0]=c(f,0,e[0]);for(let c=1;c<=b;c++){const b=e[c];e[c]=d(f,c,b,e[c-1],a);a=b;}}return e[b];}
